files.content:
:root {
  --bg: #1a1c2c;
  --panel: #2b2d42;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #9a9cb5;
  --border: #5d5f7a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--panel);
  padding: 28px 24px;
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.45);
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.95rem;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.9rem;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--muted);
}

input, select, button {
  width: 100%;
  font: inherit;
  font-size: 1rem;
  padding: 12px;
  margin-bottom: 18px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
}

input:focus, select:focus, button:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 205, 117, 0.35);
}

select:hover, input:hover {
  border-color: var(--muted);
}

button {
  background: var(--accent);
  color: var(--bg);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.45);
  transition: transform 0.05s, box-shadow 0.05s;
}

button:hover {
  filter: brightness(1.08);
}

button:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 rgba(0, 0, 0, 0.45);
}

.output-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  margin-bottom: 18px;
}

.output-label {
  font-size: 0.85rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--muted);
}

#result {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  word-break: break-all;
  text-align: right;
}

.formula {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.35rem; }
  #result { font-size: 1.3rem; }
}

const temperatureInput = document.getElementById('temperature');
const directionSelect = document.getElementById('direction');
const convertButton = document.getElementById('convert');
const resultOutput = document.getElementById('result');

function convertTemperature(rawValue, direction) {
  const trimmed = rawValue.trim();
  if (trimmed === '') return 'Error';

  const value = Number(trimmed);
  if (!Number.isFinite(value)) return 'Error';

  let converted;
  if (direction === 'c-to-f') {
    converted = value * 9 / 5 + 32;
  } else if (direction === 'f-to-c') {
    converted = (value - 32) * 5 / 9;
  } else {
    return 'Error';
  }

  if (!Number.isFinite(converted)) return 'Error';
  return converted.toFixed(2);
}

function handleConvert() {
  const rawValue = temperatureInput.value;
  const direction = directionSelect.value;
  resultOutput.textContent = convertTemperature(rawValue, direction);
}

convertButton.addEventListener('click', handleConvert);

temperatureInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    handleConvert();
  }
});

resultOutput.textContent = '--';
